### 1. Analysis & Pre-Thinking

**Core Requirements:**
- Extract markdown block-parsing logic into a dedicated utility file (`src/utils/markdownParser.js`)
- Restructure fence info parsing: language (first), filename (second, optional), `extra` (rest)
- Remove all duplicated parsing functions from both `ChapterBlock.vue` and `Document.vue`
- Create new parser file with clean exported functions

**Strategic Approach:**
1. Create `src/utils/markdownParser.js` with: block-type helpers, fence detection/parsing (new info format), chapter boundary detection (`isInsideCodeFence`), `parseBlocks`, `getChildChapterBlocks`, `collectAllChildContent`, and chapter-level parsing (`parseChapters`, `parseChapter`, `markAllFinished`, `markLastUnfinished`)
2. Update `src/utils/markdownParser.js`: add helper exports needed by both components
3. Refactor `Document.vue` to import from the new parser, remove all local duplicate functions
4. Refactor `ChapterBlock.vue` similarly

**Dependencies & Risks:**
- Both files use identical parsing helpers - extract once and reuse
- The info-string parsing change will affect file naming in both parsers (need unified approach)
- Need to preserve reactive state management on both pages
- Must maintain all current event emissions and props/computed behavior from each file

**Target Files:**
- `src/utils/markdownParser.js` — create (all block/chapter parsing logic)
- `src/components/document/ChapterBlock.vue` — modify (replace duplicate code with imports/use calls)
- `src/components/document/Document.vue` — modify (replace duplicate code with imports/use calls)

---

### 2. Code Block Formatting & Proposed Changes

#### New File: `src/utils/markdownParser.js`

```js /home/codx-junior-projects/codx-junior/client/src/utils/markdownParser.js
/**
 * Hash generator for stable block keys
 */
function generateHash(str) {
  let hash = 0
  for (const char of str) {
    hash = (hash << 5) - hash + char.charCodeAt(0)
    hash |= 0
  }
  return hash
}

/**
 * Heading detection helpers
 */
function isHeading(line) {
  return /^#{1,6}\s+/.test(line)
}

function getHeadingLevel(line) {
  const match = line.match(/^(#+)\s+/)
  return match ? match[1].length : 0
}

function getHeadingText(line) {
  return line.replace(/^#+\s+/, '').trim()
}

/**
 * Strip first heading line from content
 */
function stripHeaderFromContent(content) {
  const lines = content.split('\n')
  if (lines.length > 0 && isHeading(lines[0])) {
    return lines.slice(1).join('\n').trim()
  }
  return content
}

/**
 * Select renderer based on block type and file path
 */
function getRenderer(blockType, fileName) {
  if (fileName) return 'code'
  if (blockType === 'markdown' || blockType === 'md') return 'md'
  if (blockType === 'html') return blockType
  return 'code'
}

/**
 * Detect fence markers (``` or ~~~) with optional info string
 */
function getFence(line) {
  const match = line.match(/^( {0,3})(`{3,}|~{3,})(.*)$/)
  if (!match) return null
  return {
    char: match[2][0],
    length: match[2].length,
    info: match[3].trim()
  }
}

/**
 * Check if a line is a valid closing fence
 */
function isClosingFence(line, fence) {
  const lineFence = getFence(line)
  return !!(
    lineFence &&
    fence &&
    lineFence.char === fence.char &&
    lineFence.length >= fence.length &&
    !lineFence.info
  )
}

/**
 * Count matching closing fences ahead from index
 */
function countClosingFencesAhead(lines, fromIndex, fence) {
  let count = 0
  for (let i = fromIndex + 1; i < lines.length; i++) {
    if (isClosingFence(lines[i], fence)) count++
  }
  return count
}

/**
 * Decide if an anonymous fence should open a nested block or close the outer one
 */
function isNestedAnonymousFence(lines, index, currentType, currentFence) {
  const isMarkdownBlock =
    currentType === 'markdown' || currentType === 'md'
  return isMarkdownBlock && countClosingFencesAhead(lines, index, currentFence) >= 2
}

/**
 * Check if position is inside a code fence (any nesting level)
 */
function isInsideCodeFence(lines, lineIndex) {
  let currentFence = null
  let nestStack = []

  for (let i = 0; i < lineIndex; i++) {
    const fence = getFence(lines[i])
    if (!fence) continue

    if (!currentFence) {
      // First fence opens a block
      currentFence = fence
      nestStack = [fence]
      continue
    }

    const lastNested = nestStack[nestStack.length - 1]
    if (lastNested && isClosingFence(lines[i], lastNested)) {
      // Close the nested level
      nestStack.pop()
      continue
    }

    if (!nestStack.length && isClosingFence(lines[i], currentFence)) {
      // Current block closed
      if (isNestedAnonymousFence(lines, i, 'unknown', currentFence)) {
        nestStack.push(fence)
        continue
      }
      currentFence = null
      nestStack = []
    }
  }

  return !!currentFence
}

/**
 * Parse content string into typed blocks with fence handling
 * 
 * Fences use syntax: language file.txt extra1 extra2...
 * - first token → block type / language
 * - second (optional) → filename stored as `fileName`
 * - rest → stored in `extra` array for future flags
 */
function parseBlocks(content, getRendererFn = getRenderer) {
  const blocks = []
  const lines = content.split('\n')
  let currentType = 'markdown'
  let currentContent = []
  let currentFileName = ''
  let inCodeBlock = false
  let currentFence = null
  let nestedFences = []

  function addBlock() {
    const blockContent = currentContent.join('\n')
    blocks.push({
      type: currentType,
      content: blockContent,
      hash: generateHash(blockContent),
      fileName: currentFileName,
      renderer: getRendererFn(currentType, currentFileName),
      finished: false
    })
    // Mark all previous blocks as completed
    for (let i = 0; i < blocks.length - 1; i++) {
      blocks[i].finished = true
    }
    resetBlock()
  }

  function resetBlock() {
    currentType = 'markdown'
    currentContent = []
    currentFileName = ''
    currentFence = null
    nestedFences = []
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const fence = getFence(line)

    // Opening a new fenced block
    if (!inCodeBlock && fence && fence.info.trim()) {
      if (currentContent.length) addBlock()

      const parts = fence.info.split(/\s+/).filter(Boolean)
      inCodeBlock = true
      currentFence = fence
      currentType = parts[0] || 'text'
      currentFileName = parts[1] || ''
      // Extra tokens after filename (stored but not yet attached to blocks)
      continue
    }

    if (!inCodeBlock) {
      currentContent.push(line)
      continue
    }

    const topNested = nestedFences[nestedFences.length - 1]

    // Close a nested level
    if (topNested && isClosingFence(line, topNested)) {
      nestedFences.pop()
      currentContent.push(line)
      continue
    }

    // Open a new nested fence inside markdown blocks
    if (currentType === 'markdown' || currentType === 'md') {
      const innerFence = getFence(line)
      if (innerFence && innerFence.info && !isClosingFence(line, currentFence)) {
        nestedFences.push(innerFence)
        currentContent.push(line)
        continue
      }
    }

    // Close the top-level fence
    const allNestedClosed = !nestedFences.length
    if (allNestedClosed && isClosingFence(line, currentFence)) {
      if (isNestedAnonymousFence(lines, i, currentType, currentFence)) {
        nestedFences.push(currentFence)
        currentContent.push(line)
        continue
      }
      addBlock()
      inCodeBlock = false
      continue
    }

    // Default case: content line inside a fence
    currentContent.push(line)
  }

  // Flush remaining markdown content after the last code block
  if (currentContent.length) addBlock()
  for (let i = 0; i < blocks.length; i++) {
    blocks[i].finished = true
  }

  return blocks
}

/**
 * Collect full markdown output of a chapter with children
 */
function collectAllChildContent(chapter) {
  const headerLine = getHeadingText(chapter.content.split('\n')[0])
  let contentWithoutHeader = stripHeaderFromContent(chapter.content || '')
  let allContent = contentWithoutHeader

  if (chapter.children && chapter.children.length > 0) {
    for (let i = 0; i < chapter.children.length; i++) {
      const childFullContent = collectAllChildContent(chapter.children[i])
      allContent += '\n' + childFullContent
    }
  }

  return headerLine ? headerLine + '\n\n' + allContent : allContent
}

/**
 * Parse content into chapter objects with nested children
 */
function parseChapters(content, loading) {
  const lines = content.split('\n')
  const chapters = []
  let i = 0

  while (i < lines.length) {
    const line = lines[i]

    if (isHeading(line) && !isInsideCodeFence(lines, i)) {
      const chapter = parseChapter(lines, i)
      chapters.push(chapter)
      i = chapter.endIndex
    } else if (!chapters.length && line.trim()) {
      // Collect intro content before first heading
      const introContent = []
      while (i < lines.length && (!isHeading(lines[i]) || isInsideCodeFence(lines, i))) {
        introContent.push(lines[i])
        i++
      }
      const fullIntro = introContent.join('\n').trim()
      if (fullIntro) {
        chapters.push({
          level: 0,
          title: 'Introduction',
          content: fullIntro,
          children: [],
          hash: generateHash(fullIntro),
          finished: false
        })
      }
    } else {
      i++
    }
  }

  if (!loading) {
    markAllFinished(chapters)
  } else if (chapters.length > 0) {
    markLastUnfinished(chapters)
  }

  return chapters
}

/**
 * Parse a single chapter from lines, including child/chapter sections
 */
function parseChapter(lines, startIndex) {
  const headingLine = lines[startIndex]
  const level = getHeadingLevel(headingLine)
  const title = getHeadingText(headingLine)
  const content = [headingLine]
  const children = []
  let i = startIndex + 1

  while (i < lines.length) {
    const line = lines[i]

    if (isHeading(line) && !isInsideCodeFence(lines, i)) {
      const nextLevel = getHeadingLevel(line)

      if (nextLevel <= level) break

      if (nextLevel === level + 1) {
        const childChapter = parseChapter(lines, i)
        children.push(childChapter)
        i = childChapter.endIndex
        continue
      }

      if (nextLevel > level + 1) {
        content.push(line)
        i++
        continue
      }
    }

    content.push(line)
    i++
  }

  return {
    level,
    title,
    content: content.join('\n'),
    children,
    hash: generateHash(content),
    endIndex: i,
    finished: false
  }
}

/**
 * Recursively mark all chapters as completed
 */
function markAllFinished(chapters) {
  for (let i = 0; i < chapters.length; i++) {
    const chapter = chapters[i]
    chapter.finished = true
    if (chapter.children && chapter.children.length > 0) {
      markAllFinished(chapter.children)
    }
  }
}

/**
 * Recursively find last chapter and mark it unfinished
 */
function markLastUnfinished(chapters) {
  if (!chapters.length) return
  for (let i = chapters.length - 1; i >= 0; i--) {
    const chapter = chapters[i]
    if (chapter.children && chapter.children.length > 0) {
      markLastUnfinished(chapter.children)
      return
    }
    if (!chapter.finished) continue
    chapter.finished = false
    return
  }
}

/**
 * Parse blocks inside a child chapter content
 */
function parseChildBlocks(contentWithoutHeader, getRendererFn = getRenderer) {
  return parseBlocks(contentWithoutHeader || '', getRendererFn)
}

export default {
  generateHash,
  isHeading,
  getHeadingLevel,
  getHeadingText,
  stripHeaderFromContent,
  getRenderer,
  getFence,
  isClosingFence,
  countClosingFencesAhead,
  isNestedAnonymousFence,
  isInsideCodeFence,
  parseBlocks,
  collectAllChildContent,
  parseChapters,
  parseChapter,
  markAllFinished,
  markLastUnfinished,
  parseChildBlocks
}
