<script setup>
import ChapterBlock from './ChapterBlock.vue'
import * as parser from '@/utils/markdownParser'
</script>

<template>
  <div class="flex flex-col @container/document">
    <ChapterBlock
      v-for="(chapter, index) in chapters"
      :key="'chapter-' + chapter.level + '-' + index"
      :chapter="chapter"
      :blocks="getChapterBlocks(chapter)"
      :files="files"
      :documentId="documentId"
      :docProject="docProject"
      :chat="chat"
      :message="message"
      @add-file="handleFileAdd"
      @copy-chapter="handleCopyChapter"
      @create-task="handleCreateTask"
      @generate-code="handleGenerateCode"
      @reload-file="handleReloadFile"
      @open-file="handleOpenFile"
      @save-file="handleSaveFile"
      @edit-message="handleEditMessage"
      @sub-task="handleSubTask"
    >
      <template #chapter-actions="{ chapter, fullContent }">
        <slot 
          name="chapter-actions" 
          :chapter="chapter"
          :full-content="fullContent"
        />
      </template>
    </ChapterBlock>
  </div>
</template>

<script>
export default {
  props: {
    content: { type: String, default: '' },
    files: { type: Array, default: null },
    project: { type: Object, default: null },
    chat: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    documentId: { type: String, default: '' },
    message: { type: Object, default: null }
  },
  emits: [
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'edit-message',
    'sub-task',
    'copy-chapter',
    'create-task'
  ],
  data() {
    return {}
  },
  computed: {
    chapters() {
      return parser.parseChapters(this.content || '', this.loading)
    },
    docProject() {
      return this.project || this.$project
    }
  },
  methods: {
    getChapterBlocks(chapter) {
      const contentWithoutHeader = parser.stripHeaderFromContent(chapter.content || '')
      return parser.parseBlocks(contentWithoutHeader, parser.getRenderer)
    },
    handleCopyChapter(chapterData) {
      this.$emit('copy-chapter', chapterData)
    },
    handleCreateTask(taskData) {
      this.$emit('create-task', taskData)
    },
    handleFileAdd(fileData) {
      this.$emit('add-file', fileData)
    },
    handleGenerateCode(codeData) {
      this.$emit('generate-code', codeData)
    },
    handleReloadFile(reloadData) {
      this.$emit('reload-file', { file: reloadData, message: this.message })
    },
    handleOpenFile(filePath) {
      this.$emit('open-file', filePath)
    },
    handleSaveFile(saveData) {
      this.$emit('save-file', saveData)
    },
    handleEditMessage(editData) {
      this.$emit('edit-message', editData)
    },
    handleSubTask(taskData) {
      this.$emit('sub-task', taskData)
    }
  }
}
</script>
